  const size_t base = bh * (size_t)S * (size_t)D;

  // CUTE global tensors for this (batch, head): row-major [S, D]
  Tensor mQ = make_tensor(make_gmem_ptr(Q + base), make_shape(S, D), make_stride(D, Int<1>{}));
  Tensor mK = make_tensor(make_gmem_ptr(K + base), make_shape(S, D), make_stride(D, Int<1>{}));
  Tensor mV = make_tensor(make_gmem_ptr(V + base), make_shape(S, D), make_stride(D, Int<1>{}));
  Tensor mO = make_tensor(make_gmem_ptr(O + base), make_shape(S, D), make_stride(D, Int<1>{}));

  // Dynamic shared memory carve-out
  extern __shared__ char smem_raw[];
  float*  red = reinterpret_cast<float*>(smem_raw);            // 32 floats scratch
  float*  sPf = red + 32;                                      // Br*S floats (P)
  __half* sQh = reinterpret_cast<__half*>(sPf + (size_t)Br * S); // Br*D halfs (Q tile)

  Tensor sQ = make_tensor(make_smem_ptr(sQh), make_shape(Int<Br>{}, D), make_stride(D, Int<1>{}));
  Tensor sP = make_tensor(make_smem_ptr(sPf), make_shape(Int<Br>{}, S), make_stride(S, Int<1>{}));

  // ---- Stage Q tile [Br, D] into shared (coalesced over d) ----
  #pragma unroll
  for (int r = 0; r < Br; ++r) {
    int gr = q0 + r;
    for (int d = tid; d < D; d += TPB) {
      sQ(r, d) = (gr < S) ? mQ(gr, d) : __float2half(0.0f);
    }
  }
  __syncthreads();

  // ---- QK^T: thread t computes S[r, key=t] for all Br rows ----
  float s_reg[Br];
  #pragma unroll
  for (int r = 0; r < Br; ++r) s_reg[r] = 0.0f;

  if (tid < S) {
    for (int d = 0; d < D; ++d) {
      float kv = __half2float(mK(tid, d));
      #pragma unroll
      for (int r = 0; r < Br; ++r) {
        s_reg[r] += __half2float(sQ(r, d)) * kv;
      }
    }
    #pragma unroll
    for (int r = 0; r < Br; ++r) s_reg[r] *= scale;
  } else {
    #pragma unroll
    for (int r = 0; r < Br; ++r) s_reg[r] = -INFINITY;
  }

  // ---- Softmax over keys (one key per thread -> block reductions) ----
  #pragma unroll
  for (int r = 0; r < Br; ++r) {
    float mx = blockReduceMax(s_reg[r], red);
    float e  = expf(s_reg[r] - mx);          // exp(-inf)=0 for padding keys
    float su = blockReduceSum(e, red);
    sP(r, tid) = e / su;
  }
  __syncthreads();

  // ---- P V: thread t owns output columns d = tid + c*TPB (coalesced) ----
  const int nd = (D + TPB - 1) / TPB;        // columns per thread (<= MAXDPC)
  float acc[Br][MAXDPC];
  #pragma unroll
  for (int r = 0; r < Br; ++r)
    #pragma unroll
    for (int c = 0; c < MAXDPC; ++c) acc[r][c] = 0.0f;

  for (int j = 0; j < S; ++j) {
    float p[Br];
    #pragma unroll
    for (int r = 0; r < Br; ++r) p[r] = sP(r, j);   // broadcast from shared
    for (int c = 0; c < nd; ++c) {
      int d = tid + c * TPB;
      if (d < D) {
        float v = __half2float(mV(j, d));
        #pragma unroll
        for (int r = 0; r < Br; ++r) acc[r][c] += p[r] * v;
      }
    }
  }

  // ---- Write output ----
  for (int c = 0; c < nd; ++c) {
    int d = tid + c * TPB;
    if (d < D) {
      #pragma unroll
      for (int r = 0; r < Br; ++r) {
        int gr = q0 + r;
        if (gr < S) mO(gr, d) = __float2half(acc[r][c]);
      }
    }
  }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be [B,H,S,D]");
  TORCH_CHECK(Q.scalar_type() == at::kHalf &&
              K.scalar_type() == at::kHalf &&
              V.scalar_type() == at::kHalf, "Q,K,V must be float16");

  auto Qc = Q.contiguous();
  auto Kc = K.contiguous();
  auto Vc = V.contiguous();

  const int64_t B = Qc.size(0);
  const int64_t H = Qc.size(1);
  const int64_t S = Qc.size(2);
  const int64_t D = Qc.size(3);
  TORCH_CHECK(Kc.size(0) == B && Kc.size(1) == H && Kc.size(2) == S && Kc.size(3) == D, "K shape mismatch");
  TORCH_CHECK(Vc.size(0) == B && Vc.size(1) == H && Vc.size(2) == S && Vc.size(3) == D, "V shape mismatch");

  constexpr int Br     = 4;
  constexpr int TPB    = 256;
  constexpr int MAXDPC = 8;    // supports D up to TPB*MAXDPC = 2048

  TORCH_CHECK(S <= TPB, "sequence length must be <= 256 for this kernel");
  TORCH_CHECK(D <= TPB * MAXDPC, "head dim too large for this kernel");
  TORCH_CHECK(S > 0 && D > 0, "empty tensors");

  auto Out = torch::empty({B, H, S, D}, Qc.options());

  const float scale = (float)(1.0 / std::sqrt((double)D));

  dim3 block(TPB);
  dim3 grid((unsigned)((S + Br - 1) / Br), (unsigned)(B * H));

  const size_t smem = 32 * sizeof(float)
                    + (size_t)Br * S * sizeof(float)
                    + (size_t)Br * D * sizeof(__half);

  auto stream = c10::cuda::getCurrentCUDAStream().stream();
  sdpa_kernel<Br, TPB, MAXDPC><<<grid, block, smem, stream>>>(
      reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
      reinterpret_cast<__half*>(Out.data_ptr<at::Half>()),
      (int)S, (int)D, scale);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sdpa_kernel launch failed: ", cudaGetErrorString(err));
  return Out;
}
